w:r.w:t:
R = ... [cos(gam), -sin(gam), 0;... sin(gam), cos(gam), 0;... 0, 0, 1]*... [cos(bet), 0, sin(bet);... 0, 1, 0;... -sin(bet), 0, cos(bet);]*... [1, 0, 0;... 0, cos(alf), -sin(alf);... 0, sin(alf), cos(alf);] %Кусочек нужный для фаз маяка, используя модель магнитных линий syms w t real simplify(R*[cos(w*t)+sin(w*t);cos(w*t)+sin(w*t);cos(w*t)+sin(w*t)]) % r = norm([x,y,z]) u = x/r; v = y/r; w = z/r; B = (Bm/r^3).*... [3*u*v, 3*u^2-1;... 3*v^2-1, 3*u*v;... 3*v*w, 3*u*w] V = R*B %GenV = matlabFunction(V); %save GenV syms ax ay az bx by bz real aa = [ax,ay,az]; bb = [bx,by,bz];
%{ out = simplify(1/( 1 - sqrt( (sum(aa.^2) - sum(bb.^2) )^2 + 4*(sum(aa.*bb))^2 )/(sum(aa.^2) + sum(bb.^2)) ))
dax = diff(out, ax) fplot(subs(dax, [ay, az, bx, by, bz], [1, 1, 1, 1, 1])); day = diff(out, ay) daz = diff(out, az)
dbx = diff(out, bx) dby = diff(out, by) dbz = diff(out, bz) %}
%a(1) = ab.a1; a(2) = ab.a2; a(3) = ab.a3; %b(1) = ab.b1; b(2) = ab.b2; b(3) = ab.b3;
%aa(1) = V(1,1); aa(2) = V(2,1); aa(3) = V(3,1); %bb(1) = V(1,2); bb(2) = V(2,2); bb(3) = V(3,2);
%{ disp("Обычный расчёт") aa = double(subs(a,[x, y, z, Bm, alf, bet, gam],[2, 2, 2, 1, deg2rad([25, 10, 10])])); bb = double(subs(b,[x, y, z, Bm, alf, bet, gam],[2, 2, 2, 1, deg2rad([10, 10, 10])]));
BB = double(subs(B,[x, y, z, Bm],[2, 2, 2, 1]));
disp("Амплитуды В") sqrt(BB(:,1).^2+BB(:,2).^2)
disp("Фаза В") tan(BB(:,2)./BB(:,1))
disp("Норма В") norm(sqrt(BB(:,1).^2+BB(:,2).^2))
disp("Амплитуды V") sqrt(aa.^2+bb.^2)
disp("Фазы V") tan(bb./aa)
disp("Норма V") norm(sqrt(aa.^2+bb.^2))
clear aa bb clear BB %}

c = cross(aa,bb)
%c = a.*b;

cc = cross(...
    (Bm/r^3)*[3*u*v; 3*v^2-1; 3*v*w], ...
    (Bm/r^3)*[3*u^2-1; 3*u*v; 3*u*w])

%cc = (Bm/r^3)*[3*u*v; 3*v^2-1; 3*v*w].*(Bm/r^3).*[3*u^2-1; 3*u*v; 3*u*w];
invMat = inv([ ...
    (Bm/r^3)*[3*u*v; 3*v^2-1; 3*v*w], ...
    (Bm/r^3)*[3*u^2-1; 3*u*v; 3*u*w], ...
    cc]);
R_r1 = [aa',bb',c']*invMat;%R result

%simplify(R_r1 == R_r2);
%CalcRotMatrix1 = matlabFunction(simplify(R_r1));
%CalcRotMatrix2 = matlabFunction(simplify(R_r2));
%save CalcRotMatrix1
%save CalcRotMatrix2

%symvar
num_R = double(subs(R_r,[x, y, z, Bm, alf, bet, gam],[1, 1, 1, 1, deg2rad([0, 90, 25])]))
num_R_true = double(subs(R,[alf, bet, gam],[deg2rad([0, 90, 25])]))
%num_R_alt = double(subs(R_alt,[x, y, z, Bm, alf, bet, gam],[1, 1, 1, 1, deg2rad([15, 15, 15])]))

num_bet = -asin(num_R(3,1));

if abs(num_bet) ~= pi/2
    num_alf1=asin(num_R(3,2)/sqrt(1-num_R(3,1)^2));
    num_alf2=pi*sign(num_R(3,2))-asin(num_R(3,2)/sqrt(1-num_R(3,1)^2));
    if num_R(3,3) >= 0
        num_alf = num_alf1;
    else
        num_alf = num_alf2;
    end

    if num_R(1,1) >= 0
        num_gam = asin(num_R(2,1)/sqrt(1-num_R(3,1)^2));
    else
        num_gam = pi*sign(num_R(2,1))-asin(num_R(2,1)/sqrt(1-num_R(3,1)^2));
    end
else
    num_alf = 0;
    if num_R(2,2) >= 0
        num_gam = -asin(num_R(1,2));
    else
        num_gam = -pi*sign(num_R(1,2))+asin(num_R(1,2));
    end
end

disp(rad2deg([num_alf,num_bet,num_gam]))
